function copy(v) {
  return v === undefined ? v : JSON.parse(JSON.stringify(v));
}

var syncInst = new Engine();

function renderSync(tpl, locals) {
  try {
    return syncInst.render(tpl, { locals: locals });
  } catch (e) {
    return 'THROW ' + e.message;
  }
}

function wantOf(row) {
  return row[4] !== null ? row[4] : renderSync(row[5], copy(row[3]));
}

function rowsOf(name) {
  return CASES.filter(function (row) { return row[0].split('.')[0] === name; });
}

function syncDiffs(name) {
  var diffs = [];
  rowsOf(name).forEach(function (row) {
    var out = renderSync(row[2], copy(row[3])), want = wantOf(row);
    if (out !== want) { diffs.push(row[0] + ' ' + row[2] + ': ' + out + ' (expected ' + want + ')'); }
  });
  return diffs;
}

function asyncDiffs(name, done) {
  var rows = rowsOf(name), templates = {}, inst, diffs = [], i = 0;
  rows.forEach(function (row) { templates['/' + row[0]] = row[2]; });
  inst = new Engine({ loader: {
    async: true,
    resolve: function (to) { return to; },
    load: function (id, cb) {
      if (cb) { setImmediate(function () { cb(null, templates[id]); }); return undefined; }
      return templates[id];
    }
  } });
  function next() {
    var row = rows[i];
    if (!row) {
      try { expect(diffs).to.eql([]); } catch (e) { return done(e); }
      return done();
    }
    i += 1;
    inst.renderFile('/' + row[0], copy(row[3]), function (err, out) {
      var want = wantOf(row);
      out = err ? 'THROW ' + err.message : out;
      if (out !== want) { diffs.push(row[0] + ' ' + row[2] + ': ' + out + ' (expected ' + want + ')'); }
      next();
    });
  }
  next();
}

describe('@rhinostone/swig-jinja2 — attr, filesizeformat, forceescape, items, string and urlize, checked against Jinja2 3.1.6', function () {

  ['attr', 'filesizeformat', 'forceescape', 'items', 'string', 'urlize'].forEach(function (name) {
    it(name + ' on the sync render path', function () {
      expect(rowsOf(name).length).to.be.greaterThan(0);
      expect(syncDiffs(name)).to.eql([]);
    });

    it(name + ' on the async render path', function (done) {
      asyncDiffs(name, done);
    });
  });
});
